const raw = $input.first().json.data ?? $input.first().json.body ?? '';
const line = String(raw).split('\n').find((l) => l.startsWith('data:')) ?? '';
const rpc = JSON.parse(line.slice(5).trim());
const t = $('When Executed by Another Workflow').first().json;
let suspended = false, failed = false, reason = '', site = null;
if (rpc.result?.isError) {
  reason = rpc.result.content?.[0]?.text || 'webdev.provisionSite failed';
  // Same shape pipeline-delivery.json's own 'Prod result' node already parses for deploy.production:
  // the D14 write gate's denial text is prefixed 'suspend: ...' -- design section 04's CONTRACT is that
  // this IS the success outcome for an automation-triggered provision (a human decides via WS4).
  suspended = /^suspend:/.test(reason);
  failed = !suspended;
} else {
  try { site = JSON.parse(rpc.result?.content?.[0]?.text ?? '{}'); } catch { site = null; }
}
return [{ json: { tenantId: t.tenantId, runId: t.runId, suspended, failed, reason, site } }];

const raw = $input.first().json.data ?? $input.first().json.body ?? '';
const line = String(raw).split('\n').find((l) => l.startsWith('data:')) ?? '';
const rpc = JSON.parse(line.slice(5).trim());
if (rpc.result?.isError) throw new Error(rpc.result.content?.[0]?.text ?? 'approvals.request failed');
let a = {}; try { a = JSON.parse(rpc.result?.content?.[0]?.text ?? '{}'); } catch {}
const p = $('Parse provision result').first().json;
return [{ json: { ok: true, action: 'provision_suspended', tenantId: p.tenantId, runId: p.runId, approvalId: a.id ?? null } }];
